def transform(grid):
    sep = next(c for c in range(len(grid[0])) if all(row[c] == 5 for row in grid))
    left_w = sep
    right_start = sep + 1
    out = [[4] * (len(grid[0]) - right_start) for _ in grid]
    for r, row in enumerate(grid):
        for c in range(min(left_w, len(out[r]))):
            if row[c] == 9 and right_start + c < len(row) and row[right_start + c] == 4:
                out[r][c] = 3
    return out
